class ModelSpec:
    """Shared behaviour: declared fields, constraints, dict round-trip."""

    ENTITY: str = ""
    FIELDS: Tuple[str, ...] = ()
    CONSTRAINTS: Dict[str, Dict[str, Any]] = {}
    MONEY_FIELDS: Tuple[str, ...] = ()
    _FIELD_PY: Dict[str, str] = {}
    TITLE: str = ""
    SUMMARY: str = ""

    @classmethod
    def required_fields(cls) -> Tuple[str, ...]:
        return tuple(
            name
            for name in cls.FIELDS
            if (cls.CONSTRAINTS.get(name) or {}).get("required")
        )

    @classmethod
    def declared_types(cls) -> Dict[str, str]:
        return {
            name: str((cls.CONSTRAINTS.get(name) or {}).get("type") or "str")
            for name in cls.FIELDS
        }

    @classmethod
    def field_constraints(cls, name: str) -> Dict[str, Any]:
        return dict(cls.CONSTRAINTS.get(name) or {})

    @classmethod
    def from_dict(cls, payload: Optional[Dict[str, Any]]) -> "ModelSpec":
        """Build an instance from a payload, ignoring undeclared keys.

        A field the payload does not carry takes the dataclass default. A
        field that is REQUIRED and absent is filled with its type's neutral
        value -- never a domain value -- so a handler called directly (with an
        empty payload, as the smoke suite does) answers instead of raising. The
        ROUTE refuses a payload missing a required field with HTTP 422 before
        any handler runs: that is where a gap is refused, and it is not filled.
        """
        source = payload if isinstance(payload, dict) else {}
        kwargs: Dict[str, Any] = {}
        constraints = cls.CONSTRAINTS or {}
        for name in cls.FIELDS:
            attribute = cls._FIELD_PY.get(name, name)
            if name in source and source[name] is not None:
                kwargs[attribute] = source[name]
                continue
            rules = constraints.get(name) or {}
            if not rules.get("required"):
                continue
            declared = str(rules.get("type") or "str")
            if declared == "int":
                kwargs[attribute] = 0
            elif declared in ("float", "money"):
                kwargs[attribute] = 0.0
            elif declared == "bool":
                kwargs[attribute] = False
            else:
                kwargs[attribute] = ""
        known = {f.name for f in _dataclass_fields(cls)}  # type: ignore[arg-type]
        return cls(**{key: value for key, value in kwargs.items() if key in known})  # type: ignore[call-arg]

    def to_dict(self) -> Dict[str, Any]:
        out: Dict[str, Any] = {}
        for name in self.FIELDS:
            out[name] = getattr(self, self._FIELD_PY.get(name, name), None)
        return out


