#: The entity each capability's POST route saves to. Read by the Factory's
#: round-trip probes and by the isolation check -- the table and the route
#: cannot name different things.
ROUTE_ENTITIES: Dict[str, str] = {
    capability_id: str(entity_for(capability_id) or capability_id)
    for capability_id in MODELS
}

_NUMBER_TYPES = {"int", "float", "money"}

#: The integer range SQLite (and Postgres' bigint) can hold. A number outside
#: it is refused at the edge rather than handed to the driver, which would
#: raise OverflowError inside the request.
_INT_MIN = -(2 ** 63) + 1
_INT_MAX = (2 ** 63) - 1


def _rejection_headers(field: str, reason: str, allowed: Any = None) -> Dict[str, str]:
    from app.auth import _rejection

    return _rejection(field, reason, allowed)


def _refuse(field: str, reason: str, detail: str, allowed: Any = None) -> HTTPException:
    return HTTPException(status_code=422, detail=detail, headers=_rejection_headers(field, reason, allowed))


def _coerce_scalar(field: str, value: Any, declared: str) -> Any:
    """Coerce, or refuse with the field's own name -- never fill a gap."""
    if declared in ("int", "float", "money"):
        if isinstance(value, bool):
            raise _refuse(field, "wrong_type", field + " must be a number")
        if isinstance(value, (int, float)):
            number = float(value)
        else:
            text = str(value).strip()
            try:
                number = float(text)
            except (TypeError, ValueError):
                raise _refuse(field, "wrong_type", field + " must be a number")
        # NaN and the infinities are numbers JSON cannot carry back: a stored
        # one makes an answer unrenderable, so they are refused here.
        if not math.isfinite(number):
            raise _refuse(field, "wrong_type", field + " must be a finite number")
        if declared == "int":
            if number != int(number):
                raise _refuse(field, "wrong_type", field + " must be a whole number")
            if not (_INT_MIN <= int(number) <= _INT_MAX):
                raise _refuse(field, "out_of_range", field + " is outside the range this platform stores")
            return int(number)
        return number
    if declared == "bool":
        if isinstance(value, bool):
            return value
        text = str(value).strip().lower()
        if text in ("true", "1", "yes", "on"):
            return True
        if text in ("false", "0", "no", "off", ""):
            return False
        raise _refuse(field, "wrong_type", field + " must be true or false")
    if isinstance(value, str):
        return value
    if isinstance(value, bool) or isinstance(value, (int, float)):
        return str(value)
    raise _refuse(field, "wrong_type", field + " must be text")


def validate_capability_payload(capability_id: str, payload: Any) -> Dict[str, Any]:
    """The edge contract: refuse anything the model does not declare.

    The rejection is DATA (a field, a reason, the accepted values) so a caller
    can correct itself; nothing is defaulted and no gap is filled.
    """
    if not isinstance(payload, dict):
        raise _refuse("payload", "not_an_object", "payload must be an object")
    reserved = refuse_reserved_keys(payload)
    if reserved:
        raise _refuse(reserved, "reserved_key", "payload may not carry " + reserved)
    reject_invalid_payload(capability_id, payload)
    model = MODELS[capability_id]
    constraints = getattr(model, "CONSTRAINTS", {}) or {}
    clean: Dict[str, Any] = {}
    for name in list(getattr(model, "FIELDS", []) or []):
        if name not in payload:
            continue
        rules = constraints.get(name) or {}
        value = payload[name]
        if value is None:
            continue
        declared = str(rules.get("type") or "str")
        clean[name] = _coerce_scalar(name, value, declared)
        allowed = rules.get("allowed_values")
        if allowed is not None and clean[name] not in allowed:
            raise _refuse(
                name,
                "not_allowed",
                name + " must be one of: " + ", ".join(str(v) for v in allowed),
                allowed,
            )
        low, high = rules.get("min"), rules.get("max")
        if isinstance(clean[name], (int, float)) and not isinstance(clean[name], bool):
            if low is not None and clean[name] < low:
                raise _refuse(name, "out_of_range", name + " must be at least " + str(low))
            if high is not None and clean[name] > high:
                raise _refuse(name, "out_of_range", name + " must be at most " + str(high))
    return clean


def _subjects(handler_answer: Dict[str, Any]) -> List[authority.LayerValue]:
    out: List[authority.LayerValue] = []
    for item in handler_answer.get("subjects") or []:
        if not isinstance(item, dict):
            continue
