            )
        )
    return out


def _labelled(
    tenant_id: str,
    answer: Dict[str, Any],
    extra_subjects: Optional[List[authority.LayerValue]] = None,
) -> Dict[str, Any]:
    """Stamp an answer with the authority the route resolved, for this tenant."""
    subjects = _subjects(answer) + list(extra_subjects or [])
    labelled = authority.label_answer(
        tenant_id, subjects, headline=str(answer.get("error") or "")
    )
    return labelled


def _capability_or_404(capability_id: str) -> str:
    if capability_id not in MODELS:
        raise HTTPException(status_code=404, detail="unknown capability: " + str(capability_id))
    return capability_id


def _run_capability(capability_id: str, payload: Dict[str, Any], tenant_id: str) -> Dict[str, Any]:
    """Run a capability's handler, tenant in hand, and never crash the route."""
    import importlib

    module = importlib.import_module("app.actions." + capability_id)
    try:
        return module.handle(payload, {"tenant_id": tenant_id})
    except TypeError:
        return module.handle(payload)
    except Exception as exc:  # noqa: BLE001 -- a refusal, never a 500
        return {"ok": False, "error": scrub_error(exc), "error_kind": "handler_failed"}


