"""Shared plumbing for the capability handlers (no capability logic here).

Each handler owns its own domain decisions; these helpers only keep the
envelope consistent: one refusal shape, one success shape, one way to tag a
statement with the authority layer it came from. The route resolves precedence
and stamps the tenant -- a handler has no tenant of its own.
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, List, Optional, Sequence

#: Layer numbers, mirroring the versioned ladder (precedence.v1).
LAYER_CERTIFIED = 1
LAYER_DOCUMENTS = 2
LAYER_FORMULAS = 3
LAYER_PROCEDURES = 4


def subject(layer: int, object_id: str, value: Any, text: str = "") -> Dict[str, Any]:
    """One statement of an answer, tagged with the layer that produced it."""
    return {
        "layer": int(layer),
        "object_id": str(object_id),
        "value": value,
        "text": str(text or ""),
    }


def refuse(reason: str, *, kind: str = "refused", **extra: Any) -> Dict[str, Any]:
    """The body a capability answers when it will not do the thing."""
    out: Dict[str, Any] = {"ok": False, "error": str(reason), "error_kind": kind}
    out.update(extra)
    return out


def blocked(block_id: str, reason: str, answers: Dict[str, Any]) -> Dict[str, Any]:
    """A capability's fail-closed answer when a block it calls refuses."""
    return refuse(
        "block " + str(block_id) + " refused: " + str(reason),
        kind="dependency_failed",
        block=block_id,
        blocks=block_summary(answers),
    )


def block_summary(answers: Dict[str, Any]) -> Dict[str, Any]:
    """What each bound block answered, without copying a whole payload."""
    out: Dict[str, Any] = {}
    for block_id in sorted(answers or {}):
        answer = answers[block_id]
        entry: Dict[str, Any] = {"status": "unknown"}
        if isinstance(answer, dict):
            entry["status"] = str(answer.get("status") or ("error" if answer.get("error") else "success"))
            error = answer.get("error")
            if error:
                entry["error"] = str(error)[:200]
        out[block_id] = entry
    return out


def ok(
    capability_id: str,
    *,
    record: Dict[str, Any],
    result: Dict[str, Any],
    subjects: Sequence[Dict[str, Any]],
    blocks: Dict[str, Any],
) -> Dict[str, Any]:
    """The body a capability answers when it did the thing."""
    return {
        "ok": True,
        "capability_id": capability_id,
        "record": dict(record),
        "result": dict(result),
        "subjects": list(subjects),
        "blocks": block_summary(blocks),
    }


def text_of(record: Dict[str, Any], *names: str, default: str = "") -> str:
    for name in names:
        value = (record or {}).get(name)
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return default


def number_of(record: Dict[str, Any], name: str, default: float = 0.0) -> float:
    value = (record or {}).get(name)
    if isinstance(value, bool) or value is None:
        return default
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def whole_of(record: Dict[str, Any], name: str, default: int = 0) -> int:
    value = (record or {}).get(name)
    if isinstance(value, bool) or value is None:
        return default
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def money_view(capability_id: str) -> Dict[str, Any]:
    """Whether this capability's money figures may be labelled with a currency.

    The currency is read from app.money_settings (the operator's setting, never
    a literal here). With none declared the check reports WITHHELD and the
    figures are still recorded -- the platform does not invent a currency.
    """
    from app import formulas
    from app.money_settings import MoneySettingMissing

    try:
        from app.money_settings import currency

        return formulas.money_check(currency=currency())
    except MoneySettingMissing:
        return formulas.money_check(currency=None)
    except Exception as exc:  # noqa: BLE001 -- a settings failure is WITHHELD
        return {"status": "WITHHELD", "reason": type(exc).__name__}


def declared_state(record: Dict[str, Any], field: str = "membership_state") -> str:
    return text_of(record, field, default="")


def brief_dict(kind: str, record: Dict[str, Any], **facts: Any) -> Dict[str, Any]:
    """A language-layer brief as data (offline provider, deterministic)."""
    from app import llm

    try:
        return llm.resolve_brief(kind, record, **facts)
    except Exception as exc:  # noqa: BLE001 -- a brief never fails a capability
        return {"text": "", "provider": llm.PROVIDER_OFFLINE, "error": type(exc).__name__}


def steps_summary(workflow_answer: Any) -> List[Dict[str, Any]]:
    """The per-step verdict of a workflow answer, for the capability's result."""
    if not isinstance(workflow_answer, dict):
        return []
    out: List[Dict[str, Any]] = []
    for item in workflow_answer.get("results") or []:
        if not isinstance(item, dict):
            continue
        out.append(
            {
                "step_id": item.get("step_id"),
                "block": item.get("block"),
                "status": item.get("status"),
            }
        )
    return out


def workflow_completed(answer: Any) -> bool:
    """A pipeline is only done when the workflow itself says completed."""
    if not isinstance(answer, dict):
        return False
    return str(answer.get("status") or "").strip().lower() == "completed"


def counts_from(rows: Iterable[Dict[str, Any]], predicate) -> int:
    return sum(1 for row in rows or () if predicate(row or {}))

# frontend/

`src/App.tsx` is the operator console's source of record: the same console the
image serves at `/` (`app/static/index.html`), written as a component so the
UI has a maintainable home.

Both drive the platform's real routes:

* `GET /v1/capabilities` — discovers the shipped capabilities and their fields;
* `POST /v1/<capability>` / `GET /v1/<capability>` — creates and lists a
  tenant's records;
* `GET /v1/dashboard` and `POST /v1/shop_dashboard_reporting` — the shop brief;
* `GET /v1/retrieval` — search over the co-op's own records;
* `GET /v1/formulas` — the co-op's own rules.

There is deliberately **no `package.json`**: the served console is a
dependency-free page the image ships as-is, and this tree carries no build the
Dockerfile would have to run (a bundler here would need a network to install
itself, and this platform is offline by design). If the co-op later wants a
bundled build, add `package.json` with a `build` script **and** the Dockerfile
step that runs it — an unbuilt frontend is decoration.
