"""The co-op's authoritative calculations (precedence layer 3: formulas).

Every number a coordinator acts on is computed here, in one place, from named
inputs with units -- so the repair bench, the parts shelf, the rota and the
dues ledger cannot disagree about the same rule. The capability handlers call
these; nothing re-implements them inline.

A threshold that belongs to the customer (a reorder level, a dues amount) is an
input to a formula, never a constant in it. There is no currency and no tax
rate in this module: money amounts flow through app.money_settings at the point
of use, so an amount is never scaled by a rate nobody declared.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, Iterable, List, Optional, Sequence

FORMULA_LAYER = 3
FORMULA_LAYER_LABEL = "formulas"
FORMULA_VERSION = "1.0.0"


@dataclass(frozen=True)
class Formula:
    """One named calculation: inputs with units, output with a unit."""

    name: str
    purpose: str
    inputs: Dict[str, str]
    unit: str
    expression: str
    layer: int = FORMULA_LAYER
    version: str = FORMULA_VERSION

    def to_dict(self) -> Dict[str, Any]:
        return {
            "name": self.name,
            "purpose": self.purpose,
            "inputs": dict(self.inputs),
            "unit": self.unit,
            "expression": self.expression,
            "layer": self.layer,
            "layer_label": FORMULA_LAYER_LABEL,
            "version": self.version,
        }


def _number(value: Any, *, label: str) -> float:
    if isinstance(value, bool) or value is None:
        raise ValueError(label + " must be a number")
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            raise ValueError(label + " must be a number")
        try:
            return float(text)
        except ValueError as exc:
            raise ValueError(label + " must be a number, not " + repr(value)) from exc
    raise ValueError(label + " must be a number")


def _whole(value: Any, *, label: str) -> int:
    number = _number(value, label=label)
    if number != int(number):
        raise ValueError(label + " must be a whole number")
    return int(number)


# ── the formulas ────────────────────────────────────────────────────────

def reorder_point_breached(stock_on_hand: Any, reorder_level: Any) -> bool:
    """True when a part has fallen to or below its reorder level.

    The boundary is the rule: stock EQUAL to the reorder level is due for
    reorder, not the level minus one. Tested on the line, not beside it.
    """
    stock = _whole(stock_on_hand, label="stock_on_hand")
    level = _whole(reorder_level, label="reorder_level")
    if stock < 0 or level < 0:
        raise ValueError("stock_on_hand and reorder_level are not negative")
    return stock <= level


def reorder_quantity(stock_on_hand: Any, reorder_level: Any, target_level: Any) -> int:
    """How many units to order to bring a part back up to its target level."""
    stock = _whole(stock_on_hand, label="stock_on_hand")
    level = _whole(reorder_level, label="reorder_level")
    target = _whole(target_level, label="target_level")
    if target < level:
        raise ValueError("target_level is at or above reorder_level")
    shortfall = target - stock
    return shortfall if shortfall > 0 else 0


def parts_consumed_per_ticket(consumed: Any, tickets_completed: Any) -> float:
    """Average parts consumed per completed repair, 0 when nothing completed."""
    used = _number(consumed, label="consumed_this_period")
    completed = _whole(tickets_completed, label="tickets_completed")
    if completed <= 0:
        return 0.0
    return round(used / completed, 4)


def dues_outstanding(dues_amount: Any, amount_paid: Any) -> float:
    """What a member still owes for the period. Never negative: an
    overpayment is a credit, not a debt in the other direction."""
    owed = _number(dues_amount, label="dues_amount")
    paid = _number(amount_paid, label="amount_paid")
    outstanding = owed - paid
    return round(outstanding, 2) if outstanding > 0 else 0.0


def dues_state(dues_amount: Any, amount_paid: Any, declared_state: str = "") -> str:
    """The membership state the MONEY implies: active | lapsed | pending.

    One formula decides, so the ledger and the dashboard cannot disagree:
    nothing owed or fully paid is active; a part payment is a renewal in
    progress (pending); nothing paid against dues owed is lapsed. A state
    DECLARED on the record is not consulted here -- it is kept beside this
    verdict and any disagreement is recorded as a divergence, never hidden.
    """
    owed = _number(dues_amount, label="dues_amount")
    paid = _number(amount_paid, label="amount_paid")
    if owed <= 0 or paid >= owed:
        return "active"
    if paid > 0:
        return "pending"
    return "lapsed"


def shift_coverage(covered_slots: Any, total_slots: Any) -> float:
    """Fraction of a rota's slots that have a volunteer, 0 when there are none."""
    covered = _whole(covered_slots, label="covered_slots")
    total = _whole(total_slots, label="total_slots")
    if total <= 0:
        return 0.0
    return round(covered / total, 4)


def uncovered_slots(covered: Any, total: Any) -> int:
    """Slots still needing a volunteer from the current rota."""
    covered_count = _whole(covered, label="covered_slots")
    total_count = _whole(total, label="total_slots")
    remaining = total_count - covered_count
    return remaining if remaining > 0 else 0


def ticket_throughput(open_tickets: Any, completed_tickets: Any) -> float:
    """Completed repairs per open ticket: how the bench is keeping up."""
    open_count = _whole(open_tickets, label="tickets_open")
    done = _whole(completed_tickets, label="tickets_completed")
    if open_count <= 0:
        return float(done)
    return round(done / open_count, 4)


