def evaluate(name: str, arguments: Dict[str, Any]) -> Any:
    """Run one formula by name -- the way an operator or the UI asks."""
    functions = {
        "reorder_point_breached": lambda a: reorder_point_breached(
            a.get("stock_on_hand"), a.get("reorder_level")
        ),
        "reorder_quantity": lambda a: reorder_quantity(
            a.get("stock_on_hand"), a.get("reorder_level"), a.get("target_level")
        ),
        "parts_consumed_per_ticket": lambda a: parts_consumed_per_ticket(
            a.get("consumed_this_period"), a.get("tickets_completed")
        ),
        "dues_outstanding": lambda a: dues_outstanding(a.get("dues_amount"), a.get("amount_paid")),
        "dues_state": lambda a: dues_state(
            a.get("dues_amount"), a.get("amount_paid"), a.get("membership_state")
        ),
        "shift_coverage": lambda a: shift_coverage(a.get("covered_slots"), a.get("total_slots")),
        "uncovered_slots": lambda a: uncovered_slots(a.get("covered_slots"), a.get("total_slots")),
        "ticket_throughput": lambda a: ticket_throughput(
            a.get("tickets_open"), a.get("tickets_completed")
        ),
    }
    if name not in functions:
        raise KeyError("unknown formula: " + str(name))
    return functions[name](dict(arguments or {}))


def summarise(rows: Sequence[Dict[str, Any]], *, field_name: str, default: float = 0.0) -> float:
    """Sum one numeric field across stored rows, tolerating missing values."""
    total = default
    for row in rows or ():
        value = (row or {}).get(field_name)
        if isinstance(value, bool) or value is None:
            continue
        if isinstance(value, (int, float)):
            total += float(value)
    return round(total, 4)


def count_where(rows: Iterable[Dict[str, Any]], predicate) -> int:
    """Count rows a predicate accepts -- the dashboard's one counting rule."""
    return sum(1 for row in rows or () if predicate(row or {}))

