"""The platform application: one app, one health body, one UI.

``create_app`` assembles the app the factory boots: the capability routes, the
request log (app.observe), the metrics surface (app.observability when it is
shipped, else a built-in counter), the fail-closed health body (app.health --
never a health body of this module's own) and the served console.

Nothing here reads the environment at import: CI boots this module with an
empty environment (``env -i python -c "import app.main"``), and a pilot's
settings arrive at run time. The lifespan is where the storage root is made
and the migrations run, so a deploy is up to date before it answers traffic.
"""

from __future__ import annotations

import json
import os
import time
from contextlib import asynccontextmanager
from pathlib import Path
from typing import Any, Dict, Optional

from fastapi import FastAPI, Request
from fastapi.responses import FileResponse, JSONResponse, PlainTextResponse

from app import config

ROOT = Path(__file__).resolve().parents[1]

APP_TITLE = "community bicycle repair co-op platform"
APP_VERSION = "1.0.0"


def _boot() -> Dict[str, Any]:
    """Prepare the storage root and bring the schema up to head."""
    report: Dict[str, Any] = {"storage": "", "migrations": "skipped"}
    storage = config.settings().storage_path
    if storage:
        target = Path(storage)
        try:
            target.mkdir(parents=True, exist_ok=True)
            report["storage"] = str(target)
        except OSError as exc:
            report["storage"] = "unwritable: " + type(exc).__name__
    try:
        from app.migrations import upgrade_head

        upgrade_head()
        report["migrations"] = "head"
    except ImportError:
        report["migrations"] = "app.migrations absent"
    except Exception as exc:  # noqa: BLE001 -- /health reports a failed migration
        report["migrations"] = "failed: " + type(exc).__name__
    return report


class _Metrics:
    """A request counter and latency total, mounted only when the shipped
    observability module is absent."""

    def __init__(self) -> None:
        self.requests = 0
        self.seconds = 0.0

    def observe(self, elapsed: float) -> None:
        self.requests += 1
        self.seconds += max(elapsed, 0.0)

    def render(self) -> str:
        average = (self.seconds / self.requests) if self.requests else 0.0
        return (
            "# HELP platform_requests_total Requests served\n"
            "# TYPE platform_requests_total counter\n"
            "platform_requests_total " + str(self.requests) + "\n"
            "# HELP platform_request_latency_seconds Request latency\n"
            "# TYPE platform_request_latency_seconds summary\n"
            "platform_request_latency_seconds_sum " + ("%.6f" % self.seconds) + "\n"
            "platform_request_latency_seconds_average " + ("%.6f" % average) + "\n"
            "# request count " + str(self.requests) + ", mean latency "
            + ("%.6f" % average) + " seconds\n"
        )


def _mount_observability(app: FastAPI) -> None:
    """Mount the shipped observability module; measure locally if it is absent.

    ``mount_observability`` is what the Store gate looks for, and it honours
    SENTRY_DSN and rate-limits the auth routes. When the module is not part of
    this checkout the platform still answers /metrics with a real count and
    latency -- never a route that reports nothing.
    """
    try:
        from app.observability import mount_observability

        mount_observability(app)
        return
    except ImportError:
        pass
    except Exception:  # noqa: BLE001 -- a metrics mount never stops serving
        return

    metrics = _Metrics()

    @app.middleware("http")
    async def _measure(request: Request, call_next):  # pragma: no cover - timing
        started = time.perf_counter()
        try:
            return await call_next(request)
        finally:
            metrics.observe(time.perf_counter() - started)

    @app.get("/metrics", include_in_schema=False)
    def _metrics() -> PlainTextResponse:
        return PlainTextResponse(metrics.render())


def _openapi_path() -> Optional[Path]:
    for candidate in (ROOT / "openapi.json", ROOT / "docs" / "openapi.json"):
        if candidate.is_file():
            return candidate
    return None


def create_app() -> FastAPI:
    @asynccontextmanager
    async def lifespan(application: FastAPI):
        application.state.boot = _boot()
        yield

    app = FastAPI(title=APP_TITLE, version=APP_VERSION, lifespan=lifespan)

    from app.observe import install_observability

    install_observability(app)
    _mount_observability(app)

    from app.routes import router

    app.include_router(router)

    @app.get("/health")
    def health() -> JSONResponse:
        """The shipped fail-closed health body -- never one written here."""
        from app.health import health_response

        return health_response()

    @app.get("/", include_in_schema=False)
    def console() -> Any:
        page = ROOT / "app" / "static" / "index.html"
        if not page.is_file():
            return JSONResponse(
                status_code=503,
                content={"ok": False, "error": "the console is not built into this image"},
            )
        return FileResponse(page, media_type="text/html")

    @app.get("/openapi.json", include_in_schema=False)
    def openapi_document() -> Any:
        path = _openapi_path()
        if path is None:
            return JSONResponse(
                status_code=404, content={"ok": False, "error": "openapi.json missing"}
            )
        return JSONResponse(content=json.loads(path.read_text(encoding="utf-8")))

    return app


